begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
update public.payment_settings set amount_paise=69900 where id;
select has_table('public', 'payment_orders', 'durable payment orders exist');
select has_function('public', 'apply_payment_observation', 'verified observations have a database authority');
insert into auth.users(id,aud,role,phone,phone_confirmed_at,raw_user_meta_data,raw_app_meta_data) values
 ('f1000000-0000-4000-8000-000000000001','authenticated','authenticated','+919511110001',now(),'{}','{}'),
 ('f1000000-0000-4000-8000-000000000002','authenticated','authenticated','+919511110002',now(),'{}','{}'),
 ('f1000000-0000-4000-8000-000000000003','authenticated','authenticated','+919511110003',now(),'{}','{}'),
 ('f1000000-0000-4000-8000-000000000004','authenticated','authenticated','+919511110004',now(),'{}','{}');
update public.profiles set email='fixture@example.test' where id::text like 'f1000000-%';
update public.profiles set role='admin' where id='f1000000-0000-4000-8000-000000000001';
update public.profiles set role='counselor' where id='f1000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
insert into public.counselors(id,profile_id,display_name,bio,qualifications,experience,category,specialties,languages,photo_url,published)
 values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000002','Payment Fixture','Test','Test','Test','consultant_psychologist','Test','English','https://example.test/image.png',true);
select public.save_availability_exception('f2000000-0000-4000-8000-000000000001',null,(now() at time zone 'Asia/Kolkata')::date+2,'opening',false,'08:00','23:00');
create temp table fixture(n integer primary key, booking uuid, ord uuid, start_at timestamptz);
grant all on fixture to authenticated;
create function pg_temp.make_order(n integer) returns void language plpgsql as $$
declare b uuid; o public.payment_orders; t timestamptz;
begin
 perform set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);
 select start_at into t from public.get_public_availability('f2000000-0000-4000-8000-000000000001') limit 1;
 b=public.create_booking_hold('f2000000-0000-4000-8000-000000000001',t);
 o=public.reserve_payment_order(b,'simulator');
 perform public.claim_payment_order(o.id);
 perform public.attach_payment_order(o.id,'sim_order_'||n);
 insert into fixture values(n,b,o.id,t);
end; $$;
create function pg_temp.observe(n integer,e text,p text,s text default 'captured',amount integer default 69900,currency text default 'INR') returns text language sql as $$
 select public.apply_payment_observation((select ord from fixture where fixture.n=observe.n),e,encode(extensions.digest(e,'sha256'),'hex'),p,s,amount,currency);
$$;
select pg_temp.make_order(1);
select is((select amount_paise from public.payment_orders where id=(select ord from fixture where n=1)),69900,'checkout snapshots configured price');
select throws_ok($$update public.payment_orders set amount_paise=1 where id=(select ord from fixture where n=1)$$,'23514','Payment identity is immutable','price snapshot cannot change');
select throws_ok($$update public.payment_orders set provider='razorpay' where id=(select ord from fixture where n=1)$$,'23514','Payment identity is immutable','provider cannot change');
select throws_ok($$update public.payment_orders set external_order_id='other' where id=(select ord from fixture where n=1)$$,'23514','Payment identity is immutable','external identity cannot change');
select is(public.claim_payment_order((select ord from fixture where n=1)),false,'only one worker can claim external creation');
select ok(not has_function_privilege('authenticated','public.apply_payment_observation(uuid,text,text,text,text,integer,text)','execute'),'customers cannot forge observations');
select ok(not has_function_privilege('anon','public.apply_payment_observation(uuid,text,text,text,text,integer,text)','execute'),'anonymous cannot forge observations');
select ok(not has_table_privilege('authenticated','public.payment_orders','insert'),'direct order insertion forbidden');
select ok(not has_table_privilege('authenticated','public.payment_simulator_orders','select'),'simulator state is private');
select ok(not has_table_privilege('authenticated','public.payment_events','select'),'event receipts are private');
set local role authenticated;
select is((select count(*)::int from public.payment_orders),1,'customer sees own order');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000004',true);
select is((select count(*)::int from public.payment_orders),0,'other customer cannot read order');
select throws_ok($$select public.reserve_payment_order((select booking from fixture where n=1),'simulator')$$,'42501','Customer booking required','other customer cannot pay');
select throws_ok($$select public.set_payment_price(100)$$,'42501','Administrator required','customer cannot change price');
reset role;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);
select is((public.reserve_payment_order((select booking from fixture where n=1),'simulator')).id,(select ord from fixture where n=1),'retry reuses order');
select is(pg_temp.observe(1,'auth','pay_one','authorized'),'pending','authorization alone cannot confirm');
select is((select status from public.bookings where id=(select booking from fixture where n=1)),'held','authorization retains hold');
select set_config('test.payment_expiry',(select hold_expires_at::text from public.bookings where id=(select booking from fixture where n=1)),true);
select is(pg_temp.observe(1,'failed','pay_fail','failed'),'failed','failed attempt recorded');
select is((select hold_expires_at::text from public.bookings where id=(select booking from fixture where n=1)),current_setting('test.payment_expiry'),'failure does not extend hold');
select is(pg_temp.observe(1,'success','pay_one'),'confirmed','captured payment confirms');
select is(pg_temp.observe(1,'success','pay_one'),'confirmed','same event idempotent');
select throws_ok($$select public.apply_payment_observation((select ord from fixture where n=1),'success',repeat('d',64),'pay_one','captured',69900,'INR')$$,'23514','Event identity conflict','changed event payload rejected');
select is(pg_temp.observe(1,'another-id','pay_one'),'confirmed','different event cannot duplicate capture');
select is((select count(*)::int from public.booking_audit_events where booking_id=(select booking from fixture where n=1) and action='confirmed'),1,'one confirmation audit');
select is(pg_temp.observe(1,'old-failure','pay_one','failed'),'confirmed','failure after success cannot downgrade');
select is(pg_temp.observe(1,'duplicate-capture','pay_duplicate'),'admin_review','second capture requires review');
select is((select count(*)::int from public.payment_transactions where booking_id=(select booking from fixture where n=1) and outcome='confirmed'),1,'one successful linkage');
select pg_temp.make_order(2);
update public.bookings set hold_expires_at=now()-interval '1 minute' where id=(select booking from fixture where n=2);
select is(pg_temp.observe(2,'late-free','pay_late'),'confirmed','late payment confirms free slot');
select pg_temp.make_order(3);
update public.bookings set hold_expires_at=now()-interval '1 minute' where id=(select booking from fixture where n=3);
select throws_ok($$select public.reserve_payment_order((select booking from fixture where n=3),'simulator')$$,'23514','Active booking hold required','expired hold cannot restart checkout');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000004',true);
select public.create_booking_hold('f2000000-0000-4000-8000-000000000001',(select start_at from fixture where n=3));
select is(pg_temp.observe(3,'late-conflict','pay_conflict'),'admin_review','late payment cannot displace replacement hold');
select is((select status from public.bookings where id=(select booking from fixture where n=3)),'expired','conflicting original stays expired');
update public.bookings set hold_expires_at=now()-interval '1 minute' where customer_id='f1000000-0000-4000-8000-000000000004' and start_at=(select start_at from fixture where n=3) and status='held';
select is(pg_temp.observe(3,'conflict-disappeared-replay','pay_conflict'),'admin_review','replay cannot silently resolve a captured admin exception after conflict expires');
select is((select reason from public.payment_transactions where payment_id='pay_conflict'),'slot_conflict','replay preserves original review reason');
select pg_temp.make_order(4);
select is(pg_temp.observe(4,'price','pay_price','captured',1),'admin_review','wrong amount cannot confirm');
select pg_temp.make_order(5);
select is(pg_temp.observe(5,'currency','pay_currency','captured',69900,'USD'),'admin_review','wrong currency cannot confirm');
select throws_ok($$select pg_temp.observe(5,'link','pay_one')$$,'23514','Payment belongs to another order','payment cannot be reassigned');
select pg_temp.make_order(6);
update public.bookings set hold_expires_at=now()-interval '1 minute',status='expired' where id=(select booking from fixture where n=6);
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select public.save_availability_exception('f2000000-0000-4000-8000-000000000001',null,((select start_at from fixture where n=6) at time zone 'Asia/Kolkata')::date,'blocked',false,((select start_at from fixture where n=6) at time zone 'Asia/Kolkata')::time,(((select start_at from fixture where n=6)+interval '45 minutes') at time zone 'Asia/Kolkata')::time);
select is(pg_temp.observe(6,'blocked','pay_blocked'),'admin_review','changed schedule prevents late confirmation');
select public.set_payment_price(79900);
select is((select amount_paise from public.payment_orders where id=(select ord from fixture where n=1)),69900,'existing order retains original price');
select pg_temp.make_order(7);
select is((select amount_paise from public.payment_orders where id=(select ord from fixture where n=7)),79900,'new checkout uses changed price');
insert into public.payment_simulator_orders(id,receipt,amount,currency) select external_order_id,id,amount_paise,currency from public.payment_orders where id=(select ord from fixture where n=7);
select is(public.simulate_payment_attempt((select ord from fixture where n=7),'failed')->>'status','failed','simulator persists a failed provider attempt');
select is(public.simulate_payment_attempt((select ord from fixture where n=7),'captured')->>'status','captured','simulator persists capture');
select is(public.simulate_payment_attempt((select ord from fixture where n=7),'failed')->>'status','captured','simulator cannot downgrade capture');
select ok(not has_function_privilege('authenticated','public.simulate_payment_attempt(uuid,text)','execute'),'customers cannot directly simulate provider results');
select ok(not has_function_privilege('authenticated','public.claim_payment_reconciliation(integer,text)','execute'),'customers cannot run global reconciliation');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);
select public.reschedule_booking((select booking from fixture where n=1),'f2000000-0000-4000-8000-000000000001',(select start_at from public.get_public_availability('f2000000-0000-4000-8000-000000000001') limit 1));
select set_config('test.rescheduled_start',(select start_at::text from public.bookings where id=(select booking from fixture where n=1)),true);
select is(pg_temp.observe(1,'after-reschedule','pay_one'),'confirmed','payment replay remains confirmed after reschedule');
select is((select start_at::text from public.bookings where id=(select booking from fixture where n=1)),current_setting('test.rescheduled_start'),'payment replay never restores original session time');
select is((select confirmed_payment_id from public.payment_orders where id=(select ord from fixture where n=1)),'pay_one','reschedule preserves payment linkage');
select pg_temp.make_order(8);
update public.counselors set published=false where id='f2000000-0000-4000-8000-000000000001';
select is(pg_temp.observe(8,'unpublished','pay_unpublished','captured',79900),'admin_review','unpublished counselor cannot be confirmed');
update public.counselors set published=true where id='f2000000-0000-4000-8000-000000000001';
select pg_temp.make_order(9);
update public.bookings set start_at=now()-interval '1 hour',end_at=now()-interval '15 minutes',buffer_end_at=now(),hold_expires_at=now()-interval '1 minute',status='expired' where id=(select booking from fixture where n=9);
select is(pg_temp.observe(9,'started','pay_started','captured',79900),'admin_review','started session cannot be confirmed');
select pg_temp.make_order(10);
update public.profiles set role='admin' where id='f1000000-0000-4000-8000-000000000003';
select is(pg_temp.observe(10,'changed-role','pay_role','captured',79900),'admin_review','participant role changes prevent confirmation');
update public.profiles set role='customer' where id='f1000000-0000-4000-8000-000000000003';
select pg_temp.make_order(11);
select is(pg_temp.observe(11,'amount-authorized','pay_amount_transition','authorized',1),'pending','authorization never confirms a mismatched amount');
select is(pg_temp.observe(11,'amount-captured','pay_amount_transition','captured',79900),'confirmed','authoritative captured amount can replace an earlier observation');
select is((select amount_paise from public.payment_transactions where payment_id='pay_amount_transition'),79900,'transaction records actual captured amount');
select public.record_unmatched_payment_event('simulator','early-webhook',encode(extensions.digest('early-webhook','sha256'),'hex'));
select pg_temp.make_order(12);
select lives_ok($$select pg_temp.observe(12,'early-webhook','pay_early','captured',79900)$$,'same signed event recovers after uncertain order is attached');
select is((select order_id from public.payment_events where provider='simulator' and event_id='early-webhook'),(select ord from fixture where n=12),'unmatched receipt becomes linked without a duplicate event');
select is(public.claim_payment_refresh((select ord from fixture where n=1)),true,'first customer refresh can claim a check');
select is(public.claim_payment_refresh((select ord from fixture where n=1)),false,'immediate duplicate refresh is throttled');
set local role authenticated;
select throws_ok($$select public.get_payment_exceptions()$$,'42501','Administrator required','customer cannot list admin payment exceptions');
select throws_ok($$select public.get_unmatched_payment_events()$$,'42501','Administrator required','customer cannot list unmatched events');
reset role;
select * from finish();
rollback;
